--
-- Name: erp_stock_count_item_scope_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.erp_stock_count_item_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_count_type VARCHAR(20);
    location_warehouse_id BIGINT;
BEGIN
    SELECT count_type
    INTO parent_count_type
    FROM erp_stock_count
    WHERE id = NEW.count_id
      AND tenant_id = NEW.tenant_id
      AND deleted_at IS NULL;

    IF parent_count_type = 'COUNT' AND NEW.warehouse_id IS NULL THEN
        RAISE EXCEPTION '库存调整明细必须选择仓库';
    END IF;

    IF NEW.location_id IS NOT NULL THEN
        IF NEW.warehouse_id IS NULL THEN
            RAISE EXCEPTION '选择库位时必须同时选择仓库';
        END IF;

        SELECT warehouse_id
        INTO location_warehouse_id
        FROM erp_location
        WHERE id = NEW.location_id
          AND tenant_id = NEW.tenant_id
          AND deleted_at IS NULL;

        IF location_warehouse_id IS NULL THEN
            RAISE EXCEPTION '库存调整库位不存在';
        END IF;

        IF location_warehouse_id <> NEW.warehouse_id THEN
            RAISE EXCEPTION '库存调整库位不属于所选仓库';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.erp_stock_count_item_scope_guard() OWNER TO postgres;

--
-- Name: erp_validate_receipt_receivable_sign(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.erp_validate_receipt_receivable_sign() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    ar_total NUMERIC(18, 2);
BEGIN
    SELECT total_amount
      INTO ar_total
      FROM erp_accounts_receivable
     WHERE tenant_id = NEW.tenant_id
       AND id = NEW.receivable_id
       AND deleted_at IS NULL;

    IF ar_total IS NULL THEN
        RAISE EXCEPTION '应收单不存在';
    END IF;

    IF ar_total > 0 AND (
        NEW.allocated_amount < 0
        OR NEW.allocated_discount < 0
        OR NEW.allocated_total <= 0
    ) THEN
        RAISE EXCEPTION '普通应收分摊金额必须大于0';
    END IF;

    IF ar_total < 0 AND (
        NEW.allocated_amount > 0
        OR NEW.allocated_discount > 0
        OR NEW.allocated_total >= 0
    ) THEN
        RAISE EXCEPTION '退货应收分摊金额必须小于0';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.erp_validate_receipt_receivable_sign() OWNER TO postgres;

