    adjustment_reason character varying(32),
    created_by character varying(100),
    updated_by character varying(100),
    CONSTRAINT ck_erp_stock_count_adjustment_reason CHECK (((((count_type)::text = 'COUNT'::text) AND ((adjustment_reason)::text = ANY ((ARRAY['PROFIT'::character varying, 'LOSS'::character varying, 'CORRECTION'::character varying, 'MIGRATION'::character varying, 'OTHER'::character varying])::text[]))) OR ((count_type)::text <> 'COUNT'::text)))
);


