    ADD CONSTRAINT ck_erp_sale_return_settlement_amounts CHECK (((paid_amount >= (0)::numeric) AND (discount_amount >= (0)::numeric) AND ((paid_amount + discount_amount) <= total_amount_incl_tax))) NOT VALID;


